import{_ as t,o,c as a,a3 as d}from"./chunks/framework.cNy3aYYk.js";const y=JSON.parse('{"title":"Tenant Payment Gateways — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant Payment Gateways — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/tenant-payment-gateways"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant Payment Gateways — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/tenant-payment-gateways"}]]},"headers":[],"relativePath":"developer-guide/tenant-payment-gateways.md","filePath":"developer-guide/tenant-payment-gateways.md","lastUpdated":1794259478000}'),n={name:"developer-guide/tenant-payment-gateways.md"};function r(c,e,i,l,s,p){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="tenant-payment-gateways-—-developer-guide" tabindex="-1">Tenant Payment Gateways — Developer Guide <a class="header-anchor" href="#tenant-payment-gateways-—-developer-guide" aria-label="Permalink to &quot;Tenant Payment Gateways — Developer Guide&quot;">​</a></h1><p>Free Marketplace module (<code>payment-gateways</code>, <strong>1.0.1</strong>) for workspace-owned Stripe / Creem / Kelviq credentials used by Customer Portal invoice checkout.</p><p><strong>Not</strong> Central <code>payment_gateways</code> / Cashier / <code>BillingEngine</code>. Do not reuse Central credentials for tenant CRM checkout.</p><h2 id="catalog" tabindex="-1">Catalog <a class="header-anchor" href="#catalog" aria-label="Permalink to &quot;Catalog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Slug</td><td><code>payment-gateways</code></td></tr><tr><td>Category</td><td>Billing</td></tr><tr><td><code>is_default_included</code></td><td><code>false</code></td></tr><tr><td><code>is_billable</code></td><td><code>false</code></td></tr><tr><td>Required dep</td><td><code>payments</code></td></tr><tr><td>Optional dep</td><td><code>customer-portal</code></td></tr><tr><td>Permissions</td><td><code>payment-gateways.view</code>, <code>payment-gateways.manage_integrations</code></td></tr></tbody></table><p>Migrate-only registration + <code>CatalogSeeder</code> sync. Workspaces that already had Stripe rows are auto-entitled on upgrade.</p><p>Companion bumps: <strong>payments 1.9.1</strong>, <strong>customer-portal 1.7.1</strong> (Stripe min-amount messaging; portal/staff payment method shows <code>gateway_provider</code> label).</p><h2 id="data-model" tabindex="-1">Data model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data model&quot;">​</a></h2><p>Table <code>tenant_payment_gateway_connections</code> (one row per <code>tenant_id</code> + <code>provider</code>):</p><ul><li><code>provider</code>: <code>stripe</code> | <code>creem</code> | <code>kelviq</code></li><li><code>enabled</code>, <code>is_default</code>, <code>mode</code> (<code>sandbox</code> | <code>live</code>)</li><li>Encrypted secrets + optional publishable keys</li><li><code>config</code> JSON — Creem <code>invoice_product_id</code>, Kelviq <code>invoice_plan_identifier</code></li></ul><p>Legacy <code>tenant_stripe_connections</code> rows are copied into this table on migrate; app code uses the new model only (<code>TenantPaymentGatewayConnection</code>). Stripe facades remain for refunds / old routes.</p><h2 id="services" tabindex="-1">Services <a class="header-anchor" href="#services" aria-label="Permalink to &quot;Services&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Role</th></tr></thead><tbody><tr><td><code>TenantPaymentGatewayConnectionService</code></td><td>List / update / test / disconnect / set default</td></tr><tr><td><code>TenantInvoiceCheckoutService</code></td><td>Portal checkout + multi-provider webhooks → <code>CustomerPaymentService</code></td></tr><tr><td><code>TenantStripeConnectionService</code> / <code>TenantStripeCheckoutService</code></td><td>Thin Stripe facades</td></tr></tbody></table><p>Online pay requires entitlements for <strong>both</strong> <code>payment-gateways</code> and <code>payments</code>, plus ≥1 ready connection.</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p>Staff (<code>module:payment-gateways</code>):</p><ul><li><code>GET /payment-gateways</code></li><li><code>GET\\|PUT /payment-gateways/{provider}</code></li><li><code>POST …/test</code>, <code>POST …/default</code>, <code>DELETE …</code></li></ul><p>Legacy Stripe routes under <code>/payments/integrations/stripe</code> still work but also require <code>module:payment-gateways</code>.</p><p>Portal:</p><ul><li>Invoice resource: <code>online_payment_available</code>, <code>online_payment_providers[{code,name,is_default}]</code></li><li><code>POST /portal/invoices/{id}/checkout</code> body optional <code>{ &quot;provider&quot;: &quot;stripe&quot;|&quot;creem&quot;|&quot;kelviq&quot; }</code> (default = workspace default)</li><li>Stripe Checkout: <code>StripeMoney</code> preflight for published presentment minimums; <code>amount_too_small</code> → clear 422 (no FX invent for PKR — still paisa minor units)</li><li>Payment resource: <code>method</code> stays <code>gateway</code>; <code>gateway_provider</code> is <code>stripe</code> | <code>creem</code> | <code>kelviq</code> for UI labels</li></ul><p>Webhooks:</p><ul><li>Canonical: <code>POST /webhooks/tenant/{tenant}/gateways/{provider}/customer-payments</code></li><li>Legacy Stripe URL still forwards to the same handler</li></ul><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><ul><li>Page: <code>src/pages/payment-gateways/</code></li><li>Service: <code>tenantPaymentGatewayService</code></li><li>Permissions: <code>PERMISSIONS.tenantPaymentGateways.*</code> (avoids clash with Central <code>paymentGateways</code>)</li><li>Portal invoice picker when multiple providers are ready</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p>Pest: <code>tests/Feature/Tenant/PaymentGateway/*</code>, updated portal checkout + Stripe refund/integration tests.</p><p>Playwright: payments workflow opens Payment Gateways; headed Stripe suite configures Stripe from <code>/payment-gateways</code>.</p>',27)])])}const u=t(n,[["render",r]]);export{y as __pageData,u as default};
